<script>const shell=document.getElementById('app-shell'),toggle=document.getElementById('sidebar-toggle'),sideClose=document.getElementById('sidebar-close'),overlay=document.getElementById('sidebar-overlay');const mobile=()=>window.innerWidth<=1100;if(!mobile()&&localStorage.getItem('surya-sidebar-collapsed')==='true')shell.classList.add('sidebar-collapsed');document.documentElement.classList.remove('surya-sidebar-precollapsed');toggle.onclick=()=>{if(mobile()){shell.classList.toggle('sidebar-open')}else{const collapsed=shell.classList.toggle('sidebar-collapsed');localStorage.setItem('surya-sidebar-collapsed',collapsed?'true':'false')}};const closeSide=()=>shell.classList.remove('sidebar-open');sideClose.onclick=closeSide;overlay.onclick=closeSide;window.addEventListener('resize',()=>{if(!mobile())shell.classList.remove('sidebar-open')});</script>
